policies.statement:
// reading state of the fleet of services is not a problem, so allow all actions to it

permit(
    principal,

    // having multiple actions in one policy uses the 'in' keyword with a list
    action in [
        AgentCore::Action::"ARFleetTools___get_service_status",
        AgentCore::Action::"ARFleetTools___read_metrics",
    ],
    resource == AgentCore::Gateway::"arn:aws:bedrock-agentcore:us-east-1:397345411365:gateway/arfleetgovernance-arfleetgateway-nri1sfljea"
);

// we will allow the restart action, but only when the environment is not prod

permit(
    principal, 
    action == AgentCore::Action::"ARFleetTools___restart_service",
    resource == AgentCore::Gateway::"arn:aws:bedrock-agentcore:us-east-1:397345411365:gateway/arfleetgovernance-arfleetgateway-nri1sfljea"
)
when {

    // context.input is looking at payload of request sent to the gateway
    context.input has environment && context.input.environment != "prod"
};

// allow scaling as long as the replica value isn't too high and we aren't in prod

permit(
    principal, 
    action == AgentCore::Action::"ARFleetTools___scale_service",
    resource == AgentCore::Gateway::"arn:aws:bedrock-agentcore:us-east-1:397345411365:gateway/arfleetgovernance-arfleetgateway-nri1sfljea"
)
when {

    // context.input is looking at payload of request sent to the gateway
    context.input has environment && 
    context.input has replicas && 
    context.input.environment != "prod" &&
    context.input.replicas <= 10
};

// never allow deleting of snapshots through the gateway

forbid(
    principal,
    action == AgentCore::Action::"ARFleetTools___delete_snapshot",
    resource == AgentCore::Gateway::"arn:aws:bedrock-agentcore:us-east-1:397345411365:gateway/arfleetgovernance-arfleetgateway-nri1sfljea"
);

// allow prod restarts when the user is a Fleet Operator in IAM

permit(
    principal is AgentCore::IamEntity, 
    action == AgentCore::Action::"ARFleetTools___restart_service",
    resource == AgentCore::Gateway::"arn:aws:bedrock-agentcore:us-east-1:397345411365:gateway/arfleetgovernance-arfleetgateway-nri1sfljea"
)
when {
    context.input has environment && 
    context.input.environment == "prod" &&
    principal.id like "arn:aws:sts::*:assumed-role/*FleetOperator"
};
